contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        uint256 _inputAmount
    ) public {
        require(_feeRate <= 5_000);
        require(_virtualNftReserves > 0);
        require(_inputAmount > 0 && _inputAmount <= type(uint128).max);

        c.initialize(
            address(0),
            address(0),
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(_inputAmount);

        uint256 grossOutput = _inputAmount * _virtualBaseTokenReserves / (_virtualNftReserves + _inputAmount);

        assert(
            c.initialized()
            && feeAmount == grossOutput * _feeRate / 10_000
            && netOutputAmount + feeAmount + protocolFeeAmount == grossOutput
            && feeAmount <= grossOutput
        );
    }
}

