contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 outputAmount) public {
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 feeRate = c.feeRate();
        address factory = c.factory();
        uint256 protocolFeeRate = Factory(factory).protocolFeeRate();

        uint256 inputAmount = (netInputAmount - feeAmount) - protocolFeeAmount;

        assert(
            feeAmount == inputAmount * feeRate / 10_000 &&
            protocolFeeAmount == inputAmount * protocolFeeRate / 10_000 &&
            feeAmount <= netInputAmount &&
            protocolFeeAmount <= netInputAmount
        );
    }

    receive() external payable {}
}

