contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 outputAmount) public {
        c.initialize(
            address(0),
            address(0),
            1_000_000e18,
            2_000_000e18,
            0,
            100,
            bytes32(0),
            false,
            false
        );

        require(outputAmount > 0 && outputAmount < 2**128, "bad amount");

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 vBase = c.virtualBaseTokenReserves();
        uint256 vNft = c.virtualNftReserves();
        uint256 feeRate = c.feeRate();

        require(outputAmount < vNft, "amount too large");

        uint256 denom = vNft - outputAmount;
        uint256 gross = outputAmount * vBase / denom;
        if (outputAmount * vBase % denom != 0) {
            gross += 1;
        }

        assert(
            feeAmount == gross * feeRate / 10_000 &&
            netInputAmount == gross + feeAmount + protocolFeeAmount
        );
    }

    receive() external payable {}
}

